// ===== باي موب: سحب آخر N يوم (للاستعمال اليدوي وقت الفجوات) =====
// باي موب بيرمي 500 كتير على الصفحات العميقة، فالكود بيحاول 5 مرات لكل
// صفحة بفواصل متزايدة وبيتخطى اللي يفضل فاشل، والنتيجة أحسن مجهود.
// اللي ينزل بيتحفظ ON CONFLICT (id) فمفيش تكرار ولا ضرر من إعادة التشغيل.
const auth  = $('توكن باي موب').first().json;
const token = auth && (auth.token || auth.access_token);

const DAYS      = 14;
const PAGE_SIZE = 100;         // سقف باي موب
const MAX_PAGES = 60;
const MAX_FAILS = 12;          // إجمالي صفحات فاشلة قبل ما نستسلم
const BUDGET_MS = 8 * 60000;
const DEBUG_ROW = false;       // خليها true لو عايز صف تشخيص في المخرجات
const cutoff    = Date.now() - DAYS * 24 * 60 * 60 * 1000;
const started   = Date.now();
const terminalMapping = {
  "1139384": { branch: "المعمورة",    machine: "paymob1" },
  "1157596": { branch: "المعمورة",    machine: "paymob7" },
  "1157119": { branch: "سان ستيفانو", machine: "paymob2" },
  "1029607": { branch: "سان ستيفانو", machine: "paymob3" },
  "1157121": { branch: "سان ستيفانو", machine: "paymob6" },
  "1002249": { branch: "سيدي بشر",    machine: "paymob4" },
  "1029609": { branch: "سيدي بشر",    machine: "paymob5" }
};
const allowed = Object.keys(terminalMapping);
if (!token) return DEBUG_ROW ? [{ json: { _debug: { السبب: 'التوكن مش واصل' } } }] : [];

const BASE = 'https://accept.paymob.com/api/acceptance/transactions';
const pull = (url) => this.helpers.httpRequest({
  method: 'GET', url, headers: { Authorization: token }, json: true, timeout: 60000
});
async function pullRetry(url) {
  let err = null;
  for (let a = 1; a <= 5; a++) {                     // 5 محاولات: 0،3،6،9،12 ثانية
    try { return { ok: true, data: await pull(url) }; }
    catch (e) { err = e; if (a < 5) await new Promise(r => setTimeout(r, a * 3000)); }
  }
  return { ok: false, err };
}

const out = [], seen = new Set();
const dbg = { صفحات: 0, خام: 0, فشل: 0, أقدم_يوم: null, السبب: '', ثواني: 0 };
let page = 0, fails = 0;

while (page < MAX_PAGES) {
  if (Date.now() - started > BUDGET_MS) { dbg.السبب = 'خلص وقت النود'; break; }
  page++;

  const r = await pullRetry(BASE + '?page_size=' + PAGE_SIZE + '&page=' + page);
  if (!r.ok) {
    fails++; dbg.فشل = fails;
    console.log('صفحة ' + page + ' فشلت (' + fails + '/' + MAX_FAILS + '): ' + ((r.err && r.err.message) || ''));
    if (fails >= MAX_FAILS) { dbg.السبب = 'فشل ' + fails + ' صفحة'; break; }
    continue;
  }

  const rows = Array.isArray(r.data) ? r.data : (r.data.results || []);
  if (!rows.length) { dbg.السبب = 'خلصت المعاملات'; break; }
  dbg.صفحات++; dbg.خام += rows.length;

  let oldest = Infinity;
  for (const item of rows) {
    const t = Date.parse(item.paid_at || item.created_at || '');
    if (!isNaN(t)) oldest = Math.min(oldest, t);
    if (item.success !== true) continue;
    // الملغية: بنكتبها بصفر (مش بنتخطاها) عشان لو كانت اتسجّلت بيع قبل
    // الإلغاء، الـON CONFLICT يصفّرها ويصلّح نفسه بدل ما يفضل بيع وهمي.
    const isVoid = item.is_voided === true;
    if (!isNaN(t) && t < cutoff) continue;
    const tId = String(item.terminal_id || '').trim();
    if (!allowed.includes(tId) || seen.has(item.id)) continue;
    seen.add(item.id);
    // ⚠️ is_refund = دي معاملة مرتجع | is_refunded = دي معاملة بيع اتردّت
    //    بعدين (بتفضل بيع، والمرتجع بييجي كمعاملة لوحدها). خلطهم بيخلي
    //    البيع يتقلب سالب والمبلغ يتخصم مرتين.
    const isRefund  = item.is_refund === true;
    let amount      = isVoid ? 0 : (item.amount_cents || 0) / 100;
    const feesValue = isVoid ? 0 : (Number(item.fees) || 0);
    const vatValue  = isVoid ? 0 : ((Number(item.vat_cents_bigint) || 0) / 100);
    let netAmount   = isVoid ? 0 : (amount - feesValue - vatValue);
    if (!isVoid && isRefund) { amount = -Math.abs(amount); netAmount = -Math.abs(netAmount); }

    const map = terminalMapping[tId];
    out.push({ json: {
      id: item.id, terminal_id: tId, machine_name: map.machine, branch: map.branch,
      order_id: item.order ? String(item.order.id) : null,
      type: isVoid ? 'VOID' : (isRefund ? 'REFUND' : 'SALE'),
      ammount: amount.toFixed(2), fees: feesValue.toFixed(2), vat: vatValue.toFixed(2),
      netammount: netAmount.toFixed(2), balance: null, from: null, to: map.machine,
      closed: null, done: null, is_excess: null,
      createdAt: item.paid_at, updatedAt: null
    }});
  }

  if (oldest !== Infinity) dbg.أقدم_يوم = new Date(oldest).toISOString().slice(0, 10);
  console.log('صفحة ' + page + ': ' + rows.length + ' · إجمالي للحفظ ' + out.length + ' · أقدم ' + dbg.أقدم_يوم);
  if (oldest < cutoff) { dbg.السبب = 'وصلنا لـ' + DAYS + ' يوم'; break; }
  await new Promise(res => setTimeout(res, 250));
}

dbg.ثواني = Math.round((Date.now() - started) / 1000);
console.log('انتهى: ' + (dbg.السبب || 'وقفنا عند صفحة ' + page) + ' · للحفظ ' + out.length + ' · ' + dbg.ثواني + 'ث');
if (DEBUG_ROW) out.push({ json: { _debug: dbg } });
return out;
